static void applyBrightness(unsigned percent){if(asleep)percent=0;ledcWrite(whitePWMChannel,(percent*1023+50)/100);}
static void signalWarning(){completionAt=0;secondBuzzAt=0;digitalWrite(buzzerPin,HIGH);buzzerUntil=millis()+warningMs;digitalWrite(33,LOW);redUntil=buzzerUntil;}
static void signalTimeout(){signalWarning();buzzerUntil=millis()+250;secondBuzzAt=millis()+500;redUntil=millis()+750;}
static void signalComplete(){completionAt=millis();whiteUntil=completionAt+1600;}
static void signalScan(){digitalWrite(buzzerPin,LOW);buzzerUntil=0;secondBuzzAt=0;if(redUntil){digitalWrite(33,HIGH);redUntil=0;}if(completionAt)return;applyBrightness(successBrightness);whiteUntil=millis()+confirmMs;}
static void feedbackTick(){
 uint32_t now=millis();
 if(buzzerUntil&&(int32_t)(now-buzzerUntil)>=0){digitalWrite(buzzerPin,LOW);buzzerUntil=0;}
 if(secondBuzzAt&&(int32_t)(now-secondBuzzAt)>=0){secondBuzzAt=0;digitalWrite(buzzerPin,HIGH);buzzerUntil=now+250;}
 if(redUntil&&(int32_t)(now-redUntil)>=0){digitalWrite(33,HIGH);redUntil=0;}
 if(completionAt){uint32_t t=now-completionAt;if(t<1200){uint32_t phase=t<600?t:1200-t;applyBrightness(successBrightness*phase/600);}else if(t<1450)applyBrightness(0);else if(t<1600)applyBrightness(successBrightness);else{completionAt=0;whiteUntil=0;applyBrightness(ledOn?idleBrightness:0);}}
 else if(whiteUntil&&(int32_t)(now-whiteUntil)>=0){whiteUntil=0;applyBrightness(ledOn?idleBrightness:0);}
}
